import asyncio


async def default_fetcher(url):
    await asyncio.sleep(0)
    return "OK:" + url


def fetch_all(urls, fetcher=None):
    if not urls:
        return []
    fetch = fetcher or default_fetcher

    async def gather_all():
        return list(await asyncio.gather(*[fetch(url) for url in urls[:-1]]))

    return asyncio.run(gather_all())
